def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict[chain[0]].append(chain[1])

    visited = set()
    stack = [chain[0]]

    while stack:
        current = stack.pop()
        if current in visited:
            continue
        visited.add(current)

        for next_item in chain_dict.get(current, []):
            stack.append(next_item)

    return ','.join(chain_dict[chain[0]] + chain_dict[chain[1]])
